package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"
	"unicode"
	"unicode/utf8"

	"golang.org/x/text/unicode/norm"
)

type AuditEntry struct {
	Timestamp time.Time
	User      string
	Action    string
	Resource  string
	Hash      string
}

type SearchIndex struct {
	mu      sync.RWMutex
	entries map[string][]string
	acl     map[string][]string
	audit   []AuditEntry
}

func NewSearchIndex() *SearchIndex {
	return &SearchIndex{
		entries: make(map[string][]string),
		acl:     make(map[string][]string),
		audit:   make([]AuditEntry, 0),
	}
}

func (si *SearchIndex) computeResourceHash(resource string) string {
	h := sha256.New()
	h.Write([]byte(resource))
	return hex.EncodeToString(h.Sum(nil))
}

func (si *SearchIndex) canonicalizeIdentifier(input string) string {
	normalized := norm.NFKC.String(input)
	var builder strings.Builder
	for _, r := range normalized {
		if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '_' || r == '-' || r == '.' {
			builder.WriteRune(r)
		}
	}
	return strings.ToLower(builder.String())
}

func (si *SearchIndex) validateResourceName(name string) bool {
	if len(name) == 0 || len(name) > 256 {
		return false
	}
	if !utf8.ValidString(name) {
		return false
	}
	normalized := norm.NFKC.String(name)
	for _, r := range normalized {
		if r > 127 {
			return false
		}
		if unicode.Is(unicode.Mn, r) {
			return false
		}
	}
	return true
}

func (si *SearchIndex) validateUsername(name string) bool {
	if len(name) == 0 || len(name) > 64 {
		return false
	}
	normalized := norm.NFKC.String(name)
	for _, r := range normalized {
		if r > 127 {
			return false
		}
	}
	return true
}

func (si *SearchIndex) checkAccess(user, resource string) bool {
	si.mu.RLock()
	defer si.mu.RUnlock()
	return si.checkAccessUnlocked(user, resource)
}

func (si *SearchIndex) checkAccessUnlocked(user, resource string) bool {
	canonicalUser := si.canonicalizeIdentifier(user)
	allowedResources, exists := si.acl[canonicalUser]
	if !exists {
		return false
	}
	for _, allowed := range allowedResources {
		if allowed == resource {
			return true
		}
	}
	return false
}

func (si *SearchIndex) logAccess(user, action, resource string) {
	entry := AuditEntry{
		Timestamp: time.Now(),
		User:      si.canonicalizeIdentifier(user),
		Action:    action,
		Resource:  resource,
		Hash:      si.computeResourceHash(resource),
	}
	si.audit = append(si.audit, entry)
}

func (si *SearchIndex) AddDocument(user, resource, content string) error {
	if !si.validateUsername(user) {
		return fmt.Errorf("invalid username")
	}
	if !si.validateResourceName(resource) {
		return fmt.Errorf("invalid resource name")
	}
	if !si.checkAccess(user, resource) {
		si.mu.Lock()
		si.logAccess(user, "DENIED_ADD", resource)
		si.mu.Unlock()
		return fmt.Errorf("access denied")
	}
	si.mu.Lock()
	defer si.mu.Unlock()
	si.entries[resource] = append(si.entries[resource], content)
	si.logAccess(user, "ADD", resource)
	return nil
}

func (si *SearchIndex) Search(user, query string) ([]string, error) {
	if !si.validateUsername(user) {
		return nil, fmt.Errorf("invalid username")
	}
	si.mu.RLock()
	defer si.mu.RUnlock()
	var results []string
	for resource, docs := range si.entries {
		if !si.checkAccessUnlocked(user, resource) {
			continue
		}
		for _, doc := range docs {
			if strings.Contains(strings.ToLower(doc), strings.ToLower(query)) {
				results = append(results, doc)
			}
		}
	}
	return results, nil
}

func (si *SearchIndex) GrantAccess(admin, user, resource string) error {
	if !si.validateUsername(admin) || !si.validateUsername(user) {
		return fmt.Errorf("invalid username")
	}
	if !si.checkAccess(admin, "_admin") {
		return fmt.Errorf("not authorized")
	}
	if !si.validateResourceName(resource) {
		return fmt.Errorf("invalid resource name")
	}
	si.mu.Lock()
	defer si.mu.Unlock()
	canonicalUser := si.canonicalizeIdentifier(user)
	si.acl[canonicalUser] = append(si.acl[canonicalUser], resource)
	si.logAccess(admin, "GRANT", fmt.Sprintf("%s->%s", canonicalUser, resource))
	return nil
}

func (si *SearchIndex) GetAuditLog(admin string) ([]AuditEntry, error) {
	if !si.validateUsername(admin) {
		return nil, fmt.Errorf("invalid username")
	}
	if !si.checkAccess(admin, "_admin") {
		return nil, fmt.Errorf("not authorized")
	}
	si.mu.RLock()
	defer si.mu.RUnlock()
	copyAudit := make([]AuditEntry, len(si.audit))
	copy(copyAudit, si.audit)
	return copyAudit, nil
}

func main() {
	idx := NewSearchIndex()
	idx.mu.Lock()
	idx.acl["admin"] = []string{"_admin", "docs", "secrets"}
	idx.acl["alice"] = []string{"docs"}
	idx.mu.Unlock()

	mux := http.NewServeMux()

	mux.HandleFunc("/search", func(w http.ResponseWriter, r *http.Request) {
		user := r.Header.Get("X-User")
		query := r.URL.Query().Get("q")
		results, err := idx.Search(user, query)
		if err != nil {
			http.Error(w, err.Error(), http.StatusForbidden)
			return
		}
		for _, res := range results {
			fmt.Fprintf(w, "%s\n", res)
		}
	})

	mux.HandleFunc("/grant", func(w http.ResponseWriter, r *http.Request) {
		admin := r.Header.Get("X-User")
		targetUser := r.URL.Query().Get("user")
		resource := r.URL.Query().Get("resource")
		if err := idx.GrantAccess(admin, targetUser, resource); err != nil {
			http.Error(w, err.Error(), http.StatusForbidden)
			return
		}
		fmt.Fprintf(w, "granted\n")
	})

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	log.Fatal(srv.ListenAndServe())
}
